# DISCLAMER: This file is generated by AI for testing purposes.
import json
import tempfile
import unittest
from pathlib import Path

from iSpy.config.iSpyConfig import (
    _CAMERA_CORE_KEYS,
    get_pipeline_settings,
    iSpyConfig,
    normalize_camera_entry,
)


class FrameProcessorCameraEntryTests(unittest.TestCase):
    def test_frame_processors_is_a_core_camera_key(self):
        self.assertIn("frame_processors", _CAMERA_CORE_KEYS)

    def test_normalize_keeps_assignment_out_of_pipeline_settings(self):
        entry = {
            "source": 0,
            "frame_processors": ["a", "b"],
            "pipeline": {"name": "hsv_detection", "settings": {}},
        }
        normalize_camera_entry(entry)
        self.assertEqual(entry["frame_processors"], ["a", "b"])
        self.assertNotIn("frame_processors", get_pipeline_settings(entry))

    def test_legacy_flat_pipeline_also_keeps_assignment_at_top_level(self):
        entry = {
            "source": 0,
            "frame_processors": [],
            "pipeline": "hsv_detection",
            "preset": "custom",
        }
        normalize_camera_entry(entry)
        self.assertEqual(entry["frame_processors"], [])
        self.assertEqual(entry["pipeline"]["settings"], {"preset": "custom"})


class EditorGraphConfigTests(unittest.TestCase):
    def test_old_config_without_editor_graph_loads_unchanged(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "config.json"
            path.write_text(
                json.dumps(
                    {
                        "camera_configs": {
                            "cam": {
                                "source": 0,
                                "pipeline": {"name": "hsv_detection", "settings": {}},
                            }
                        }
                    }
                )
            )
            config = iSpyConfig(file_path=str(path), create=False)
            self.assertNotIn("editor_graph", config.config)

    def test_editor_graph_and_camera_assignment_round_trip(self):
        layout = {
            "version": 1,
            "grid": 20,
            "viewport": {"x": 40, "y": 20, "zoom": 0.8},
            "nodes": {
                "camera:cam": {"x": 80, "y": 80},
                "frame_processor:cam:a": {"x": 320, "y": 80},
            },
        }
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "config.json"
            path.write_text(
                json.dumps(
                    {
                        "camera_configs": {
                            "cam": {
                                "source": 0,
                                "frame_processors": ["a"],
                                "pipeline": {"name": "hsv_detection", "settings": {}},
                            }
                        },
                        "plugins": {
                            "trackers": {},
                            "utilities": {},
                            "frame_processors": {"a": {}},
                        },
                    }
                )
            )
            config = iSpyConfig(file_path=str(path), create=False)
            config.config["editor_graph"] = layout
            config.save(quiet=True)

            reloaded = iSpyConfig(file_path=str(path), create=False)
            self.assertEqual(reloaded.config["editor_graph"], layout)
            self.assertEqual(
                reloaded.config["camera_configs"]["cam"]["frame_processors"], ["a"]
            )
            self.assertNotIn(
                "frame_processors",
                get_pipeline_settings(reloaded.config["camera_configs"]["cam"]),
            )


if __name__ == "__main__":
    unittest.main()
